def sum_squares_abs_diff_squares(a: int, b: int) -> tuple:
    sq_a, sq_b = a * a, b * b
    return (sq_a + sq_b, abs(sq_a - sq_b))

def is_odd_length_palindrome(s: str) -> bool:
    # Odd length AND reads the same forwards and backwards
    return len(s) % 2 == 1 and s == s[::-1]

def remove_elements_at_two_indices(l: list, i1: int, i2: int) -> None:
    # Delete the larger index first so the smaller index stays valid
    for idx in sorted([i1, i2], reverse=True):
        del l[idx]

def get_roll_nos(data: list, criteria=None):
    marks = [m for _, m in data]
    avg = sum(marks) / len(marks) if marks else 0
    if criteria is None:
        return [r for r, _ in data]
    if criteria == 'above_average':
        return [r for r, m in data if m >= avg]
    if criteria == 'below_average':
        return [r for r, m in data if m < avg]
    if criteria == 'fail':
        return [r for r, m in data if m < 40]
    if criteria == 'toppers':
        return [r for r, m in data if m >= 90]
    return None
